+final class FileNameResolverTest extends TestCase
+{
+    private string $dir;
+
+    protected function setUp(): void
+    {
+        $this->dir = sys_get_temp_dir() . '/resolver_' . uniqid();
+        mkdir($this->dir);
+    }
+
+    protected function tearDown(): void
+    {
+        array_map('unlink', glob($this->dir . '/*'));
+        rmdir($this->dir);
+    }
+
+    public function testSecondSameNameGetsNumber(): void
+    {
+        $resolver = new FileNameResolver();
+
+        $this->assertSame('a.csv', $resolver->reserveFreeName($this->dir, 'a.csv'));
+        $this->assertSame('a_1.csv', $resolver->reserveFreeName($this->dir, 'a.csv'));
+    }
+}
